CREATE TABLE d1(a TEXT, b INTEGER, c NUMERIC); CREATE TABLE d2(x BLOB, y BLOB); INSERT INTO d1 VALUES(1, 1, 1); INSERT INTO d1 VALUES(2, 2, 2); INSERT INTO d1 VALUES(3, 3, 3); INSERT INTO d1 VALUES(4, 4, 4); INSERT INTO d2 VALUES(1, 1); INSERT INTO d2 VALUES(2, '2'); INSERT INTO d2 VALUES('3', 3); INSERT INTO d2 VALUES('4', '4'); CREATE INDEX idx ON d1(c); CREATE INDEX idx1 ON d2(x, y); CREATE UNIQUE INDEX idx2 ON d2(x);